      try (rewrite !union_iff;
            repeat match goal with
            | |- context [fv_tm_tm_tm ?q] => rewrite (in_fv_swap_tm z q)
            | |- context [fv_tm_tm_brs ?q] => rewrite (in_fv_swap_brs z q)
            | |- context [fv_tm_tm_co ?q] => rewrite (in_fv_swap_co z q)
            | |- context [fv_tm_tm_constraint ?q] => rewrite (in_fv_swap_constraint z q)
            end; tauto);
      try (apply in_fv_swap_tm).
  - destruct b; simpl;
      try (rewrite !empty_iff; tauto);
      try (rewrite !union_iff;
            repeat match goal with
            | |- context [fv_tm_tm_tm ?q] => rewrite (in_fv_swap_tm z q)
            | |- context [fv_tm_tm_brs ?q] => rewrite (in_fv_swap_brs z q)
            end; tauto);
      try (apply in_fv_swap_brs).
  - destruct g; simpl;
      try (rewrite !empty_iff; tauto);
      try (rewrite !union_iff;
            repeat match goal with
            | |- context [fv_tm_tm_tm ?q] => rewrite (in_fv_swap_tm z q)
            | |- context [fv_tm_tm_co ?q] => rewrite (in_fv_swap_co z q)
            | |- context [fv_tm_tm_constraint ?q] => rewrite (in_fv_swap_constraint z q)
            end; tauto);
